    private static byte[] visibleBytes(Pc1CrxDecoder.Decoded image)throws IOException{byte[] storage=image.storage();ByteArrayOutputStream out=new ByteArrayOutputStream();for(int row=image.height-1;row>=0;row--)out.write(storage,row*image.stride,image.width*(image.format==0?3:4));return out.toByteArray();}
    private static byte[] visibleBytes(NativeRgbImage image)throws IOException{byte[] storage=image.bgr24();ByteArrayOutputStream out=new ByteArrayOutputStream();for(int row=image.height-1;row>=0;row--)out.write(storage,row*image.stride,image.width*3);return out.toByteArray();}
    private static byte[] visibleBytes(NativeInverseAlphaImage image)throws IOException{byte[] storage=image.abgr32();ByteArrayOutputStream out=new ByteArrayOutputStream();for(int row=image.height-1;row>=0;row--)out.write(storage,row*image.stride,image.width*4);return out.toByteArray();}
